p5.js sketch: interactive Lunda shading
Paste into the p5.js Web Editor. The sketch draws a 45° ray and colours each unit square it enters according to parity.
// Lunda shading: colour unit squares by (i+j) mod 2
// while a 45° ray travels between the pulli

let rows = 8, cols = 8;
let cell = 50;
let margin = 40;
let path = [];
let t = 0;

function setup() {
  createCanvas(cols*cell + 2*margin, rows*cell + 2*margin);
  generatePath();
}

function draw() {
  background(245);
  translate(margin, margin);

  // Draw all unit squares, coloured if visited
  let visited = {};
  let n = min(floor(t), path.length);
  for (let k = 0; k &lt; n; k++) {
    let i = floor(path[k].y / cell);
    let j = floor(path[k].x / cell);
    visited[i+","+j] = true;
  }

  for (let i = 0; i &lt; rows; i++) {
    for (let j = 0; j &lt; cols; j++) {
      if (visited[i+","+j]) {
        fill((i+j) % 2 === 0 ? 255 : 30);
      } else {
        fill(230);
      }
      stroke(180);
      rect(j*cell, i*cell, cell, cell);
    }
  }

  // Pulli
  fill(20); noStroke();
  for (let i = 0; i &lt;= rows; i++)
    for (let j = 0; j &lt;= cols; j++)
      circle(j*cell, i*cell, 6);

  // Ray
  noFill(); stroke(30,90,180); strokeWeight(2);
  beginShape();
  for (let k = 0; k &lt; n; k++) vertex(path[k].x, path[k].y);
  endShape();

  t += 0.8;
  if (t &gt; path.length + 30) t = 0;
}

function generatePath() {
  path = [];
  let x = 0.5*cell, y = 0.5*cell;
  let dx = 1, dy = 1;
  for (let s = 0; s &lt; 300; s++) {
    path.push({x, y});
    if (x + dx*cell*0.5 &lt; 0 || x + dx*cell*0.5 &gt; cols*cell) dx = -dx;
    if (y + dy*cell*0.5 &lt; 0 || y + dy*cell*0.5 &gt; rows*cell) dy = -dy;
    x += dx * cell * 0.5;
    y += dy * cell * 0.5;
  }
}

An adjacency matrix ( A ) of a graph records who is connected to whom:
\[
A_{ij} =
\begin{cases}
1 & \text{if there is an edge from } i \text{ to } j \\
0 & \text{otherwise}
\end{cases}
\]
Nothing forces ( A_{ij} = A_{ji} ). A directed edge can exist in one direction only. That is the technical starting point: relationships need not be symmetric.

